// Beacon 0 is invalid, so Steam returns k_uAPICallInvalid instead of dispatching the call
var ok = steam_parties_join_party(0, gametest_async_recorder("party_join"));
show_debug_message("gametest: party_join: " + string(steam_api_last_error()));
return (!ok && string_pos("k_uAPICallInvalid", steam_api_last_error()) > 0) ? 1 : 0;

// Beacon 0 is invalid, so Steam returns k_uAPICallInvalid instead of dispatching the call
var ok = steam_parties_change_num_open_slots(0, 1, gametest_async_recorder("party_slots"));
show_debug_message("gametest: party_slots: " + string(steam_api_last_error()));
return (!ok && string_pos("k_uAPICallInvalid", steam_api_last_error()) > 0) ? 1 : 0;
